"""One-time static source preparation. Build never executes this script.
Artwork is extracted only from clean image regions; UI remains editable HTML.
"""
from pathlib import Path
from PIL import Image, ImageDraw
from html import escape
import json, shutil

ROOT=Path(__file__).resolve().parents[1]
ASSETS=ROOT/'assets/images/sections'
ASSETS.mkdir(parents=True,exist_ok=True)
records=[]
def e(s):return escape(str(s),quote=True)
def ic(name):return f'<i class="fa-solid fa-{name}" aria-hidden="true"></i>'
def a(text,cls=''):return f'<a href="#" class="{cls}">{text}</a>'
def btn(text,label=None,cls=''):return f'<button type="button" class="{cls}"'+(f' aria-label="{e(label)}"' if label else '')+f'>{text}</button>'
def crop(n,name,box,clean_badge=False):
    source=Image.open(ROOT/f'design/section-{n}.png').convert('RGB')
    box=tuple(round(v) for v in box)
    result=source.crop(box)
    if clean_badge:
        # The selected image area overlaps only the empty corner under a UI badge.
        ImageDraw.Draw(result).rectangle((0,0,min(52,result.width//4),26),fill='white')
    path=ASSETS/f's{n}-{name}.webp'
    result.save(path,quality=94)
    records.append({'section':n,'asset':str(path.relative_to(ROOT)).replace('\\','/'),'source':f'design/section-{n}.png','crop':box,'size':result.size,'cleanup':'white empty top-left badge corner' if clean_badge else None})
    return str(path.relative_to(ROOT)).replace('\\','/')
def img(path,alt='',cls=''):
    w,h=Image.open(ROOT/path).size
    return f'<img src="{path}" width="{w}" height="{h}" alt="{e(alt)}" class="{cls}" loading="lazy" decoding="async">'
def heading(n,title,desc='',eyebrow=''):
    return f'<div class="hs-heading">'+(f'<p class="hs-eyebrow">{eyebrow}</p>' if eyebrow else '')+f'<h1 id="s{n}-title" data-section-heading>{title}</h1>'+ (f'<p>{desc}</p>' if desc else '')+'</div>'
def write(n,body,accent='#ed0028',extra='',dark=False):
    tag='footer' if n==25 else 'section'
    html=f'<{tag} id="section-{n}" class="section-{n} hacom-section {extra}" style="--accent:{accent}" aria-labelledby="s{n}-title">\n<div class="hacom-container hs-shell">\n{body}\n</div>\n</{tag}>\n'
    # Keep static section source easy to inspect and edit without a framework.
    html=html.replace('><','>\n<')
    (ROOT/f'src/sections/section-{n}.html').write_text(html,encoding='utf-8')
def benefits(items,icons=None):
    icons=icons or ['truck-fast','shield-halved','headset','gift','gear','award']
    return '<ul class="hs-benefits">'+''.join('<li>'+ic(icons[i%len(icons)])+'<span>'+t+'</span></li>' for i,t in enumerate(items))+'</ul>'
def strip(items,cta='Khám phá ngay',intro='Khám phá thêm',sub='Đội ngũ chuyên gia HACOM luôn sẵn sàng hỗ trợ'):
    return '<div class="hs-strip"><div class="hs-strip-intro">'+ic('gift')+f'<span><strong>{intro}</strong><small>{sub}</small></span></div><div class="hs-strip-items">'+''.join(a(ic(['shield-halved','gear','headset','cube'][i%4])+'<span>'+t+'</span>') for i,t in enumerate(items))+'</div>'+a(cta+' '+ic('arrow-right'),'hs-cta')+'</div>'
def filters(items,label='Xem tất cả sản phẩm'):
    return '<nav class="hs-filters" tabindex="0" aria-label="Nhóm sản phẩm"><div>'+''.join(a((ic('fire')+' ' if i==0 else '')+t,'is-selected' if i==0 else '') for i,t in enumerate(items))+'</div>'+a(label+' '+ic('arrow-right'),'hs-viewall')+'</nav>'
def category_tiles(n,names,box,columns=8):
    x1,y1,x2,y2=box; step=(x2-x1)/columns
    return '<div class="hs-categories" tabindex="0" aria-label="Danh mục">'+''.join(a(img(crop(n,f'category-{i+1}',(x1+i*step+9,y1,x1+(i+1)*step-9,y2)),name)+f'<span>{name}</span>') for i,name in enumerate(names))+'</div>'
def brandrow(brands):
    out=[]
    branddir=ROOT/'assets/images/brands';branddir.mkdir(exist_ok=True)
    for i,name in enumerate(brands):
        origin=Path('D:/hacom-0309/assets/images/branding')/(name.lower()+'.webp')
        if origin.exists():
            target=branddir/origin.name;shutil.copyfile(origin,target);content=img(str(target.relative_to(ROOT)).replace('\\','/'),name)
        else:content=f'<strong>{e(name)}</strong>'
        out.append(a(content,'is-selected' if i==0 else ''))
    return '<div class="hs-brands" tabindex="0" aria-label="Thương hiệu">'+''.join(out)+'</div>'
def callout(title,desc,cta='Khám phá ngay'):
    return '<div class="hs-callout">'+ic('microchip')+f'<span><strong>{title}</strong><small>{desc}</small></span>'+a(cta+' '+ic('arrow-right'),'hs-white-button')+'</div>'
def productrail(n,products,geometry,trade=False,horizontal=False,ratings=True):
    x,step,y1,y2=geometry;cards=[]
    for i,p in enumerate(products):
        name,spec,price,old,rating,badge=p
        # Crop product artwork only, excluding title/price/button/heart areas.
        image=crop(n,f'product-{i+1}',(x+i*step+10,y1,x+i*step+125,y2) if horizontal else (x+i*step+60,y1,x+(i+1)*step-60,y2),clean_badge=not horizontal)
        cards.append('<article class="hs-product">'+('<span class="hs-product-badge">'+badge+'</span>' if badge else '')+btn(ic('heart'),f'Yêu thích {name}','hs-heart')+img(image,name,'hs-product-image')+'<div class="hs-product-copy"><h3>'+e(name)+'</h3><p class="hs-product-spec">'+e(spec)+'</p><div class="hs-product-bottom"><div><strong class="hs-price">'+price+'</strong>'+('<del>'+old+'</del>' if old else '')+('<p class="hs-rating"><span>★</span> '+rating+'</p>' if ratings and rating else '')+'</div>'+btn((ic('cart-shopping')+' Đổi ngay') if trade else ic('cart-shopping'),f'{"Đổi ngay" if trade else "Thêm vào giỏ"}: {name}','hs-cart')+'</div>'+('<small class="hs-installment">Trả góp 0% từ '+['2.749.000','2.499.000','3.082.000','2.249.000','3.749.000','2.416.000'][i%6]+'đ/tháng</small>' if n==5 else '')+'</div></article>')
    return f'<div class="hs-products {"hs-horizontal-products" if horizontal else ""}" style="--product-count:{len(products)}" tabindex="0" aria-label="Danh sách sản phẩm">'+''.join(cards)+'</div>'

