def servicegrid(names):
    icons=['desktop','gear','fan','display','shield-halved','building','coins','headset','cube','screwdriver-wrench']
    return '<div class="hs-service-grid">'+''.join(a(ic(icons[i%len(icons)])+f'<strong>{name}</strong>'+ic('arrow-right')) for i,name in enumerate(names))+'</div>'
