    art=crop(n,'hero-artwork',d['hero'])
    hero=f'<div class="hs-chapter-hero {"is-light" if d.get("light") else ""}">'+img(art,d['topic'],'hs-chapter-art')+f'<div class="hs-chapter-copy"><p class="hs-chapter-label">CHAPTER {d["ch"]} / {d["topic"]}</p><h1 id="s{n}-title" data-section-heading>{d["title"]}</h1><p class="hs-chapter-description">{d["desc"]}</p>'+(benefits(HERO_BENEFITS[n]) if HERO_BENEFITS[n] else '')+a(('Định giá thiết bị ngay' if n==18 else 'Khám phá dịch vụ' if n==17 else 'Khám phá ngay')+' '+ic('arrow-right'),'hs-cta')+'</div></div>'
